const getDeepClone = () => {
  const mod = require('../../../src/options/clone');
  if (typeof mod === 'function') return mod;
  if (mod && typeof mod.default === 'function') return mod.default;
  if (mod && typeof mod.deepClone === 'function') return mod.deepClone;
  throw new Error('deepClone export not found');
};

const deepClone = getDeepClone();

describe('deepClone', () => {
  test('clones primitive values correctly', () => {
    expect(deepClone('hello')).toBe('hello');
    expect(deepClone(42)).toBe(42);
    expect(deepClone(true)).toBe(true);
    expect(deepClone(false)).toBe(false);
    expect(deepClone(null)).toBeNull();
    expect(deepClone(undefined)).toBeUndefined();
  });

  test('clones arrays deeply including nested structures', () => {
    const original = [1, [2, { a: 3 }], { b: 4 }];
    const clone = deepClone(original);

    // should be a different reference for the top-level array
    expect(clone).not.toBe(original);
    expect(clone).toEqual(original);

    // nested array/object should also be cloned (no shared references)
    expect(clone[1]).not.toBe(original[1]);
    expect(clone[1][1]).not.toBe(original[1][1]);

    // modify clone and ensure original remains unchanged
    clone[1][1].a = 999;
    expect(original[1][1].a).toBe(3);
  });

  test('clones plain objects deeply', () => {
    const original = {
      x: 1,
      y: { z: [ { w: 5 } ] }
    };
    const clone = deepClone(original);

    expect(clone).not.toBe(original);
    expect(clone).toEqual(original);

    // nested properties should be cloned
    expect(clone.y).not.toBe(original.y);
    expect(clone.y.z).not.toBe(original.y.z);
    expect(clone.y.z[0]).not.toBe(original.y.z[0]);

    // mutate clone nested structures and ensure original unaffected
    clone.y.z[0].w = 99;
    expect(original.y.z[0].w).toBe(5);
  });

  test('does not throw for non-plain objects and returns a non-primitive', () => {
    const d = new Date(2020, 0, 1);
    const clone = deepClone(d);

    // Should not throw and should return an object
    expect(clone).toBeDefined();
    expect(typeof clone).toBe('object');
  });

  test('original value remains unchanged after cloning', () => {
    const original = { a: { b: [1, 2, 3] }, c: 'test' };
    const clone = deepClone(original);

    // mutate clone
    clone.a.b.push(4);
    clone.c = 'changed';

    // ensure original untouched
    expect(original.a.b).toEqual([1, 2, 3]);
    expect(original.c).toBe('test');
  });
});

