      throw new Error('normalizeAllMethods export not found');
    }
  });

  test('throws TypeError when plugin is not an object (null/undefined)', () => {
    expect(() => normalizeAllMethods(null)).toThrow(TypeError);
    expect(() => normalizeAllMethods(undefined)).toThrow(TypeError);
  });

  test('does not mutate the input plugin object', () => {
    const plugin = {
      instanceMethod: function() { return 'i'; },
      staticMethod: function() { return 's'; }
    };
    const before = {};
    Object.keys(plugin).forEach((k) => (before[k] = plugin[k]));
    const result = normalizeAllMethods(plugin);
    Object.keys(before).forEach((k) => {
      expect(plugin[k]).toBe(before[k]);
    });
    expect(typeof result).toBe('object');
    expect(result).not.toBeNull();
  });

  test('returns an object when given a valid plugin with no methods', () => {
    const plugin = {};
    const result = normalizeAllMethods(plugin);
    expect(typeof result).toBe('object');
    expect(result).not.toBeNull();
  });
});

