const path = require('../../../src/merge/prefix.js');

function getPrefixCauseFunction() {
  if (typeof path === 'function') return path;
  if (path && typeof path.prefixCause === 'function') return path.prefixCause;
  if (path && path.default && typeof path.default === 'function') return path.default;
  throw new Error('prefixCause function not found');
}

const prefixCause = getPrefixCauseFunction();

describe('prefixCause', () => {
  test('returns original message and updates cause.message with prefixed name when message is present', () => {
    const cause = new Error('boom');
    cause.name = ' BoomError'.trim();

    const old = prefixCause(cause);

    expect(old).toBe('boom');
    expect(cause.message).toBe('BoomError: boom');
    expect(cause.name).toBe('BoomError');
  });

  test('returns empty string and updates message to name when message is empty', () => {
    const cause = new Error('');
    cause.name = 'EmptyName';

    const old = prefixCause(cause);

    expect(old).toBe('');
    expect(cause.message).toBe('EmptyName');
    expect(cause.name).toBe('EmptyName');
  });

  test('throws TypeError when cause is null', () => {
    expect(() => prefixCause(null)).toThrow(TypeError);
  });

  test('does not modify message when cause.name is not a string', () => {
    const bad1 = { name: 123, message: 'x' };
    const old1 = prefixCause(bad1);

    expect(old1).toBe('x');
    expect(bad1.message).toBe('x');
    expect(bad1.name).toBe(123);
  });
});
